//! melee_fighter::tu::ftdynamics vs the C (gen/cref/tu/ftdynamics_ops.c: the whole TU, shipping contraction, recording stubs, three random
//! fighters). Generated by gen/mtu/mkdriver.py from gen/mtu/specs/ftdynamics.json; regenerate the C side with
//! `bash rust/melee_fighter/gen/mtu/regen_ftdynamics.sh`.
#![allow(static_mut_refs, non_snake_case, non_upper_case_globals, unused_variables, unused_parens, unused_unsafe, unused_mut, unused_imports, clippy::all)]
mod mtu_h;
use core::ffi::c_void;
use core::ptr::null_mut;
use melee_fighter::hooks as h;
use melee_fighter::tu::ftdynamics as m;
use melee_fighter::types::*;
use mtu_h::*;

mod ftdynamics_stubs;
mod ftdynamics_state {
    use super::*;
    include!("ftdynamics_state/gen.rs");
}
use ftdynamics_state::*;

const NG: usize = 3;
const NJ: usize = 8;
const NP: usize = 16;
static mut GO: *mut [HSD_GObj; NG] = null_mut();
static mut JO: *mut [HSD_JObj; NJ] = null_mut();
static mut FT: *mut [Fighter; NG] = null_mut();
static mut FDATA: *mut [ftData; NG] = null_mut();
static mut PARTS: *mut [[FighterBone; 64]; NG] = null_mut();
static mut CD: *mut ftCommonData = null_mut();
static mut PLINKV: [*mut HSD_GObj; 16] = [null_mut(); 16];
static mut PADB: *mut [[u8; 2048]; 96] = null_mut();

fn pick_HSD_GObj() -> *mut HSD_GObj { let r = rnd(); unsafe { if r % 6 == 0 { null_mut() } else { &raw mut (*GO)[((r >> 8) as usize) % NG] } } }
fn pick_HSD_JObj() -> *mut HSD_JObj { let r = rnd(); unsafe { if r % 6 == 0 { null_mut() } else { &raw mut (*JO)[((r >> 8) as usize) % NJ] } } }
fn pick_Fighter() -> *mut Fighter { let r = rnd(); unsafe { if r % 6 == 0 { null_mut() } else { &raw mut (*FT)[((r >> 8) as usize) % NG] } } }
fn pick_Item() -> *mut Item { null_mut() }
fn pick_HSD_DObj() -> *mut HSD_DObj { null_mut() }
pub unsafe extern "C" fn cbev1(g: *mut HSD_GObj) { t(7001); t(pi(g)); }
pub unsafe extern "C" fn cbev2(g: *mut HSD_GObj) { t(7002); t(pi(g)); }
pub unsafe extern "C" fn cbp1(g: *mut HSD_GObj) -> i32 { t(7003); t(pi(g)); (fv() & 1) as i32 }
pub unsafe extern "C" fn cbp2(g: *mut HSD_GObj) -> i32 { t(7004); t(pi(g)); (fv() & 1) as i32 }
pub unsafe extern "C" fn cbev3(g: *mut HSD_GObj, hh: *mut HSD_GObj) { t(7005); t(pi(g)); t(pi(hh)); }
fn pick_fn(kind: i32) -> usize {
    let r = rnd();
    if r & 3 == 0 { return 0; }
    match kind {
        1 => if r & 4 != 0 { cbev1 as usize } else { cbev2 as usize },
        2 => if r & 4 != 0 { cbp1 as usize } else { cbp2 as usize },
        3 => cbev3 as usize,
        _ => 0,
    }
}

fn bz<T>() -> *mut T { Box::leak(Box::new(unsafe { core::mem::zeroed::<T>() })) }
static mut DYN: *mut [ftDynamics; NG] = null_mut(); static mut ADB: *mut [[BoneDynamicsTemplate; Ft_Dynamics_NumMax as usize]; NG] = null_mut();
static mut DDP: *mut [[[DynamicsData; 3]; Ft_Dynamics_NumMax as usize]; NG] = null_mut();
static mut X10: [[*mut *mut FigaTree; 5]; NG] = [[null_mut(); 5]; NG];
static mut TREES: [[[*mut FigaTree; Ft_Dynamics_NumMax as usize]; 4]; NG] = [[[null_mut(); Ft_Dynamics_NumMax as usize]; 4]; NG];
static mut X28A: [[[u8; 2]; 8]; NG] = [[[0; 2]; 8]; NG]; static mut ARG1: [u8; 2] = [0; 2]; static mut SGK: i32 = 0;

unsafe fn install_hooks() {
    DYN = bz(); ADB = bz(); DDP = bz();
    m::ext::STAGE_INFO_GRKIND = Some(|| SGK);
}

unsafe fn world() {
    *GO = core::mem::zeroed();
    *JO = core::mem::zeroed();
    *FT = core::mem::zeroed();
    *FDATA = core::mem::zeroed();
    *CD = core::mem::zeroed();
    for i in 0..NG { fill_Fighter(&mut (*FT)[i]); }
    for i in 0..NJ { fill_HSD_JObj(&mut (*JO)[i]); }
    for i in 0..NG { fill_HSD_GObj(&mut (*GO)[i]); }
    for i in 0..NG {
        (*GO)[i].user_data = &raw mut (*FT)[i] as *mut c_void;
        (*GO)[i].hsd_obj = &raw mut (*JO)[i] as *mut c_void;
        (*GO)[i].classifier = HSD_GOBJ_CLASS_FIGHTER as _;
        (*GO)[i].next = if i + 1 < NG { &raw mut (*GO)[i + 1] } else { null_mut() };
        (*FT)[i].gobj = &raw mut (*GO)[i];
        (*FT)[i].ft_data = &raw mut (*FDATA)[i];
        (*FT)[i].grab_cb = Some(cbev1); (*FT)[i].grabbed_cb = Some(cbev3);
        (*FT)[i].kind = ((*FT)[i].kind as u32 % 27) as _; (*FT)[i].player_idx %= 4; (*FT)[i].pad_port %= 4;
        for b in 0..64 { if b < NP { fill_FighterBone(&mut (*PARTS)[i][b]); } else { (*PARTS)[i][b] = core::mem::zeroed(); (*PARTS)[i][b].x8.x0.set_flags_b1(1); } (*PARTS)[i][b].joint = &raw mut (*JO)[(i * 5 + b * 3) % NJ]; }
        (*FT)[i].parts = (*PARTS)[i].as_mut_ptr();
// the ftData pointer words: one pad block each (the C driver's order)
        { let mut pk = i * 24; macro_rules! nx { () => {{ pk += 1; (*PADB)[pk - 1].as_mut_ptr() as *mut _ }}; }
          let d = &mut (*FDATA)[i];
          d.x0 = nx!(); d.ext_attr = nx!(); d.x8 = nx!(); d.xC = nx!(); d.x10 = nx!(); d.x14 = nx!(); d.x18 = nx!(); d.x1C = nx!();
          d.x20 = nx!(); d.x24 = nx!(); d.x28 = nx!(); d.x2C = nx!(); d.x30 = nx!(); d.x34 = nx!(); d.x38 = nx!(); d.x3C = nx!();
          d.x40 = nx!(); d.x44 = nx!(); d.x48_items = nx!(); d.x4C_sfx = nx!(); d.x50 = nx!(); d.x54 = nx!(); d.x58 = nx!(); d.x5C = nx!(); }
    }
    for i in 0..NJ {
        (*JO)[i].parent = if i != 0 { &raw mut (*JO)[(i - 1) / 2] } else { null_mut() };
        (*JO)[i].child = if 2 * i + 1 < NJ { &raw mut (*JO)[2 * i + 1] } else { null_mut() };
        (*JO)[i].next = if (i & 1) != 0 && i + 1 < NJ { &raw mut (*JO)[i + 1] } else { null_mut() };
    }
    h::P_FT_COMMON_DATA = CD;
    for i in 0..16 { PLINKV[i] = null_mut(); }
    PLINKV[HSD_GOBJ_PLINK_FIGHTER as usize] = &raw mut (*GO)[0];
    h::PLINK_HEAD = Some(|link| PLINKV[link as usize]);
    {
      SGK = if fv() & 1 != 0 { Gr_Kind_Flatzone as i32 } else { 0 };
      for q in 0..NG {
        (*DYN)[q] = core::mem::zeroed(); (*ADB)[q] = core::mem::zeroed(); (*DDP)[q] = core::mem::zeroed();
        (*DYN)[q].x0.dynamicsNum = (fv() % 10) as i32; (*DYN)[q].x0.ftDynamicBones = (*ADB)[q].as_mut_ptr();
        for k in 0..Ft_Dynamics_NumMax as usize {
          (*ADB)[q][k].bone_id = (fv() % 60) as _; (*ADB)[q][k].dyn_desc.count = fv() % 5;
          for j in 0..3 {
            let d: *mut DynamicsData = &raw mut (*DDP)[q][k][j];
            (*d).next = if j < 2 && (fv() & 1) != 0 { &raw mut (*DDP)[q][k][j + 1] } else { null_mut() };
            (*d).desc.lb_unk0.jobj = &raw mut (*JO)[(fv() as usize) % NJ];
            (*d).desc.lb_unk0.translate.x = rg(); (*d).desc.lb_unk0.translate.y = rg(); (*d).desc.lb_unk0.translate.z = rg();
            (*d).desc.lb_unk0.scale.x = rg(); (*d).desc.lb_unk0.scale.y = rg(); (*d).desc.lb_unk0.scale.z = rg();
          }
          (*FT)[q].dynamic_bone_sets[k].dyn_desc.data = &raw mut (*DDP)[q][k][0];
        }
        (*FDATA)[q].x2C = &raw mut (*DYN)[q] as *mut _;
        (*FT)[q].dynamics_num = (fv() % 11) as i32;
        for a in 0..4 {
          for k in 0..Ft_Dynamics_NumMax as usize { TREES[q][a][k] = (fv() % 4) as usize as *mut FigaTree; }
          X10[q][a] = if fv() % 5 == 0 { null_mut() } else { TREES[q][a].as_mut_ptr() };
        }
        X10[q][4] = null_mut();
        (*DYN)[q].x10 = (X10[q].as_mut_ptr()) as *mut _;
        (*FT)[q].x28 = &raw mut X28A[q][1];
        for a in 0..8 { X28A[q][a][0] = (fv() % 256) as u8; X28A[q][a][1] = (fv() % 5) as u8; }
        (*FT)[q].anim_id = (fv() % 7) as i32 - 1;
        if fv() & 1 != 0 { (*FT)[q].x34_scale.y = 1.0; }
        (*FT)[q].x594.x0.set_x594_b3((fv() & 1) as _); (*FT)[q].x594.x0.set_x594_b4((fv() & 1) as _);
      }
      ARG1[0] = (fv() % 256) as u8; ARG1[1] = (fv() % 5) as u8;
    }
}
unsafe fn hworld() {
    for i in 0..NG { hash_Fighter(&(*FT)[i]); }
    for i in 0..NJ { hash_HSD_JObj(&(*JO)[i]); }
    for i in 0..NG { hash_HSD_GObj(&(*GO)[i]); }
    for i in 0..NG { for b in 0..NP { hash_FighterBone(&(*PARTS)[i][b]); } }
    for q in 0..NG { for k in 0..Ft_Dynamics_NumMax as usize { for j in 0..3 { let d = &(*DDP)[q][k][j];
        hm(d.desc.lb_unk0.unk_2C.x.to_bits()); hm(d.desc.lb_unk0.unk_2C.y.to_bits()); hm(d.desc.lb_unk0.unk_2C.z.to_bits()); hm(d.desc.lb_unk0.unk_44.to_bits()); hm(d.desc.lb_unk0.translate.x.to_bits()); hm(d.desc.lb_unk0.scale.x.to_bits()); } } }
}

#[test]
fn ftdynamics_matches_c() {
    unsafe {
        GO = bz(); JO = bz(); FT = bz(); FDATA = bz(); PARTS = bz(); CD = bz(); PADB = bz();
        preg(GO, core::mem::size_of_val(&*GO));
        preg(JO, core::mem::size_of_val(&*JO));
        preg(FT, core::mem::size_of_val(&*FT));
        preg(FDATA, core::mem::size_of_val(&*FDATA));
        preg(PADB, core::mem::size_of_val(&*PADB));
        freg(cbev1 as usize); freg(cbev2 as usize); freg(cbp1 as usize); freg(cbp2 as usize); freg(cbev3 as usize);
        ftdynamics_stubs::install();
        install_hooks();
    }
    let mut c = Check::new(include_str!("data/tu_ftdynamics_ops.txt"));
    const NOPS: u32 = 5;
    for op in 0..NOPS {
        for k in 0..500u32 {
            case(op, k);
            if std::env::var("TUV").is_ok() { eprintln!("op {op} k {k}"); }
            let mut ret = 0u32;
            let res = std::panic::catch_unwind(core::panic::AssertUnwindSafe(|| unsafe {
                world();
                let gi = (rnd() as usize) % NG;
                let g = &raw mut (*GO)[gi];
                let fp = &raw mut (*FT)[gi];
                match op {
                    0 => { m::ftCo_8009CF84(&mut *fp) }
                    1 => { let b = fv() & 1 != 0; m::ftCo_8009DD94(g, b as i32) }
                    2 => { m::ftCo_8009E0A8(g) }
                    3 => { m::ftCo_8009E614(&mut *fp) }
                    4 => { m::ftCo_8009E7B4(&mut *fp, ARG1.as_ptr() as *const [u8; 2]) }
                    _ => unreachable!(),
                }
                hworld();
            }));
            if res.is_err() { c.assert_line(op, k); continue; }
            unsafe { c.line(op, k, ret); }
        }
    }
    assert_eq!(c.done(), NOPS * 500);
}
